def parse_word(entry):
    """'f[a]mily|æ|পরিবার' -> dict(word, before, target, after, sound, bn)."""
    from .sounds import split_target
    parts = entry.split("|")
    word, before, target, after = split_target(parts[0])
    return {"text": word, "before": before, "target": target, "after": after,
            "sound": parts[1] if len(parts) > 1 else "", "bn": parts[2] if len(parts) > 2 else ""}
